import React, { useEffect, useRef } from 'react';

const TechParticles = () => {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        canvas.width = canvas.offsetWidth;
        canvas.height = canvas.offsetHeight;

        const particles = [];
        const particleCount = 50;

        class Particle {
            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.size = Math.random() * 3 + 1;
                this.speedX = Math.random() * 1 - 0.5;
                this.speedY = Math.random() * 1 - 0.5;
                this.color = `rgba(${Math.random() * 100 + 50}, ${Math.random() * 100 + 150}, 255, ${Math.random() * 0.5 + 0.3})`;
            }

            update() {
                this.x += this.speedX;
                this.y += this.speedY;

                if (this.x > canvas.width) this.x = 0;
                if (this.x < 0) this.x = canvas.width;
                if (this.y > canvas.height) this.y = 0;
                if (this.y < 0) this.y = canvas.height;
            }

            draw() {
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }


        // Replace the Cube class with this ArchLogo class
        class ArchLogo {
            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.size = Math.random() * 30 + 15; // Slightly bigger for visibility
                this.speedX = Math.random() * 0.4 - 0.2;
                this.speedY = Math.random() * 0.4 - 0.2;
                this.rotation = Math.random() * Math.PI * 2;
                this.rotationSpeed = (Math.random() - 0.5) * 0.01;
            }

            update() {
                this.x += this.speedX;
                this.y += this.speedY;
                this.rotation += this.rotationSpeed;

                if (this.x > canvas.width + 50) this.x = -50;
                if (this.x < -50) this.x = canvas.width + 50;
                if (this.y > canvas.height + 50) this.y = -50;
                if (this.y < -50) this.y = canvas.height + 50;
            }

            draw() {
                ctx.save();
                ctx.translate(this.x, this.y);
                ctx.rotate(this.rotation);

                // Arch Blue Gradient/Color
                ctx.strokeStyle = 'rgba(23, 147, 209, 0.5)';
                ctx.fillStyle = 'rgba(23, 147, 209, 0.1)'; // Subtle fill for a "ghost" logo look
                ctx.lineWidth = 1.5;
                ctx.lineJoin = 'round';

                const h = this.size;       // Total height
                const w = this.size * 1.1; // Slightly wider than tall

                ctx.beginPath();
                // 1. Start at the sharp top peak
                ctx.moveTo(0, -h / 2);

                // 2. Right side flare down
                ctx.lineTo(w / 2, h / 2);

                // 3. The curved bottom "arch"
                // This creates the distinct concave bottom of the logo
                ctx.bezierCurveTo(
                    w / 4, h / 3,
                    -w / 4, h / 3,
                    -w / 2, h / 2
                );

                // 4. Left side flare back to top
                ctx.closePath();

                ctx.fill();
                ctx.stroke();

                // 5. The Internal "Swoosh" 
                // This represents the internal shadow/line that makes it an "A"
                ctx.beginPath();
                ctx.moveTo(-w / 6, h / 10);
                ctx.bezierCurveTo(
                    0, -h / 8,
                    w / 3, 0,
                    w / 4, h / 4
                );
                ctx.stroke();

                ctx.restore();
            }
        }

        // Initialize particles and cubes
        for (let i = 0; i < particleCount; i++) {
            particles.push(new Particle());
        }

        for (let i = 0; i < 12; i++) {
            particles.push(new ArchLogo());
        }

        function connectParticles() {
            for (let i = 0; i < particleCount; i++) {
                for (let j = i + 1; j < particleCount; j++) {
                    const dx = particles[i].x - particles[j].x;
                    const dy = particles[i].y - particles[j].y;
                    const distance = Math.sqrt(dx * dx + dy * dy);

                    if (distance < 150) {
                        ctx.strokeStyle = `rgba(6, 182, 212, ${0.2 * (1 - distance / 150)})`;
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.stroke();
                    }
                }
            }
        }

        function animate() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            particles.forEach(particle => {
                particle.update();
                particle.draw();
            });

            connectParticles();

            requestAnimationFrame(animate);
        }

        animate();

        const handleResize = () => {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return (
        <canvas
            ref={canvasRef}
            className="w-full h-full absolute top-0 left-0"
            style={{ opacity: 0.6 }}
        />
    );
};

export default TechParticles;
